import { useEffect, useState } from 'react';
import ProgressBar from '../components/ProgressBar';

export default function ProgressPage() {
  const [metrics, setMetrics] = useState({
    consistency: 0,
    quiz: 0,
    tasks: 0,
  });

  const [streak, setStreak] = useState(0);

  useEffect(() => {
    // 📊 Quiz Performance
    const quizScore = parseInt(localStorage.getItem('quizScore') || '0');
    const totalQuestions = parseInt(localStorage.getItem('totalQuestions') || '1');
    const quizPercentage = Math.round((quizScore / totalQuestions) * 100);

    // 📊 Task Completion
    const completed = parseInt(localStorage.getItem('lastCompletedCount') || '0');
    const totalTasks = parseInt(localStorage.getItem('lastTotalTasks') || '1');
    const taskPercentage = Math.round((completed / totalTasks) * 100);

    // 📊 Consistency (based on completed days)
    const completedDays = JSON.parse(localStorage.getItem('completedDays') || '[]');
    const currentDay = parseInt(localStorage.getItem('currentDay') || '1');

    const consistency = Math.round((completedDays.length / currentDay) * 100);

    // 🔥 Streak Logic
    let currentStreak = 0;
    const sortedDays = [...completedDays].sort((a, b) => a - b);

    for (let i = sortedDays.length - 1; i >= 0; i--) {
      if (sortedDays[i] === currentDay - currentStreak - 1) {
        currentStreak++;
      } else {
        break;
      }
    }

    setMetrics({
      consistency,
      quiz: quizPercentage,
      tasks: taskPercentage,
    });

    setStreak(currentStreak);
  }, []);

  return (
    <div className="space-y-8">

      {/* 🔥 Header */}
      <div className="rounded-[2rem] bg-gradient-to-br from-teal-500 to-blue-500 p-8 text-white shadow-lg">
        <h2 className="text-3xl font-bold">🔥 Your Learning Progress</h2>
        <p className="mt-2 opacity-90">
          You're building consistency. Keep going 🚀
        </p>
      </div>

      {/* 📊 Metrics */}
      <div className="grid gap-6 md:grid-cols-3">
        
        <div className="rounded-2xl bg-gradient-to-br p-6 shadow-md">
          <h3 className="font-semibold">📅 Consistency</h3>
          <ProgressBar value={metrics.consistency} />
          <p className="mt-2 text-sm">{metrics.consistency}% active days</p>
        </div>

        <div className="rounded-2xl bg-white p-6 shadow-md">
          <h3 className="font-semibold">🧠 Quiz Mastery</h3>
          <ProgressBar value={metrics.quiz} />
          <p className="mt-2 text-sm">{metrics.quiz}% score</p>
        </div>

        <div className="rounded-2xl bg-white p-6 shadow-md">
          <h3 className="font-semibold">✅ Task Completion</h3>
          <ProgressBar value={metrics.tasks} />
          <p className="mt-2 text-sm">{metrics.tasks}% completed</p>
        </div>

      </div>

      {/* 🔥 Streak Card */}
      <div className="rounded-2xl bg-gradient-to-br from-orange-400 to-pink-500 p-8 text-white shadow-lg">
        <h3 className="text-xl font-semibold">🔥 Current Streak</h3>
        <p className="text-5xl font-bold mt-2">{streak} days</p>
        <p className="mt-3 opacity-90">
          {streak > 0 
            ? "You're on fire! Don't break the chain 🔥" 
            : "Start today and build your streak 💪"}
        </p>
      </div>

      {/* 🎯 Motivation Section */}
      <div className="rounded-2xl bg-white p-6 shadow-md">
        <h3 className="text-lg font-semibold">🎯 Smart Recommendation</h3>
        <p className="mt-2 text-gray-600">
          {metrics.tasks < 50 && "Focus on completing daily tasks consistently."}
          {metrics.quiz < 60 && "Revise fundamentals and retake quizzes."}
          {metrics.consistency < 70 && "Try maintaining a daily learning habit."}
          {metrics.tasks > 80 && metrics.quiz > 80 && "Amazing work! You're ahead of schedule 🚀"}
        </p>
      </div>

    </div>
  );
}
